*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-bg:         #f5f5f7;
  --color-surface:    #ffffff;
  --color-border:     #e2e2e7;
  --color-text:       #1c1c1e;
  --color-text-muted: #6e6e73;
  --color-primary:    #0071e3;
  --color-primary-hv: #0077ed;
  --color-danger:     #d70015;
  --color-danger-hv:  #bf0012;
  --color-focus:      #0071e3;
  --radius-card:      14px;
  --radius-btn:       8px;
  --shadow-card:      0 2px 12px rgba(0,0,0,.08);
  --shadow-dialog:    0 20px 60px rgba(0,0,0,.22);
  --transition:       150ms ease;
}

html { color-scheme: light dark; }

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: var(--color-bg);
  color: var(--color-text);
  line-height: 1.5;
  min-height: 100vh;
}

/* ─── Skip link ────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: .5rem 1rem;
  background: var(--color-primary);
  color: #fff;
  border-radius: var(--radius-btn);
  font-weight: 600;
  text-decoration: none;
  z-index: 9999;
  transition: top var(--transition);
}
.skip-link:focus { top: 1rem; }

/* ─── Header ───────────────────────────────────────────────────── */
.site-header {
  background: rgba(255,255,255,.85);
  backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--color-border);
  position: sticky;
  top: 0;
  z-index: 100;
}

.site-header__inner {
  max-width: 1100px;
  margin: 0 auto;
  padding: 1rem 1.5rem;
  display: flex;
  align-items: center;
  gap: 1rem;
}

.site-header__icon {
  width: 36px;
  height: 36px;
  background: linear-gradient(135deg, #7b6bf0, #0071e3);
  border-radius: 9px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  aria-hidden: true;
}

.site-header__title {
  font-size: 1.125rem;
  font-weight: 600;
  letter-spacing: -.02em;
}

/* ─── Main ─────────────────────────────────────────────────────── */
.main-content {
  max-width: 1100px;
  margin: 0 auto;
  padding: 2.5rem 1.5rem 4rem;
}

.gallery-heading {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -.03em;
  margin-bottom: .375rem;
}

.gallery-subheading {
  color: var(--color-text-muted);
  font-size: .9375rem;
  margin-bottom: 2rem;
}

/* ─── Image Grid ───────────────────────────────────────────────── */
.image-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 1.25rem;
}

/* ─── Image Card ───────────────────────────────────────────────── */
.image-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-card);
  box-shadow: var(--shadow-card);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: box-shadow var(--transition), transform var(--transition);
}

.image-card:hover {
  box-shadow: 0 6px 24px rgba(0,0,0,.12);
  transform: translateY(-2px);
}

.image-card__thumb {
  aspect-ratio: 4/3;
  overflow: hidden;
  position: relative;
  background: var(--color-border);
}

.image-card__img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 300ms ease;
}

.image-card:hover .image-card__img {
  transform: scale(1.04);
}

.image-card__body {
  padding: .875rem 1rem 1rem;
  display: flex;
  flex-direction: column;
  gap: .625rem;
  flex: 1;
}

.image-card__name {
  font-size: .9375rem;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.image-card__meta {
  font-size: .8125rem;
  color: var(--color-text-muted);
}

.image-card__actions {
  display: flex;
  justify-content: flex-end;
  margin-top: auto;
}

/* ─── Buttons ──────────────────────────────────────────────────── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: .375rem;
  padding: .4375rem .875rem;
  border: none;
  border-radius: var(--radius-btn);
  font: inherit;
  font-size: .875rem;
  font-weight: 500;
  cursor: pointer;
  text-decoration: none;
  transition: background var(--transition), color var(--transition),
              box-shadow var(--transition), opacity var(--transition);
}

.btn:focus-visible {
  outline: 2px solid var(--color-focus);
  outline-offset: 2px;
}

.btn--ghost {
  background: transparent;
  color: var(--color-danger);
  border: 1px solid var(--color-border);
}
.btn--ghost:hover {
  background: #fff0f0;
  border-color: #ffbbbb;
}

.btn--secondary {
  background: #f2f2f7;
  color: var(--color-text);
}
.btn--secondary:hover { background: #e8e8ed; }

.btn--danger {
  background: var(--color-danger);
  color: #fff;
}
.btn--danger:hover { background: var(--color-danger-hv); }

.btn--icon {
  padding: .375rem;
  border-radius: 6px;
}

/* ─── Modal / Dialog ───────────────────────────────────────────── */
dialog {
  border: none;
  border-radius: 18px;
  box-shadow: var(--shadow-dialog);
  padding: 0;
  width: min(480px, calc(100vw - 2rem));
  background: var(--color-surface);
  color: var(--color-text);
  /* center vertically in the viewport */
  margin: auto;
}

dialog::backdrop {
  background: rgba(0,0,0,.45);
  backdrop-filter: blur(4px);
}

/* opening animation */
dialog[open] {
  animation: dialog-in 200ms ease forwards;
}
@keyframes dialog-in {
  from { opacity: 0; transform: scale(.95) translateY(8px); }
  to   { opacity: 1; transform: scale(1)  translateY(0);    }
}

.dialog__header {
  padding: 1.75rem 1.75rem 0;
  display: flex;
  align-items: flex-start;
  gap: 1rem;
}

.dialog__icon-wrap {
  flex-shrink: 0;
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: #fff0f0;
  display: flex;
  align-items: center;
  justify-content: center;
}

.dialog__icon-wrap svg {
  color: var(--color-danger);
}

.dialog__title {
  font-size: 1.125rem;
  font-weight: 700;
  letter-spacing: -.02em;
  line-height: 1.3;
  padding-top: .25rem;
}

.dialog__body {
  padding: .875rem 1.75rem 0;
}

.dialog__body p {
  font-size: .9375rem;
  color: var(--color-text-muted);
  line-height: 1.6;
}

.dialog__preview {
  margin-top: 1rem;
  border-radius: 10px;
  overflow: hidden;
  border: 1px solid var(--color-border);
  aspect-ratio: 16/7;
  background: var(--color-border);
}

.dialog__preview img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.dialog__footer {
  padding: 1.5rem 1.75rem 1.75rem;
  display: flex;
  justify-content: flex-end;
  gap: .625rem;
  flex-wrap: wrap;
}

/* ─── Reduced motion ───────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; animation: none !important; }
}

/* ─── Dark mode ────────────────────────────────────────────────── */
@media (prefers-color-scheme: dark) {
  :root {
    --color-bg:         #1c1c1e;
    --color-surface:    #2c2c2e;
    --color-border:     #3a3a3c;
    --color-text:       #f5f5f7;
    --color-text-muted: #aeaeb2;
  }
  .site-header {
    background: rgba(28,28,30,.85);
  }
  .btn--secondary { background: #3a3a3c; }
  .btn--secondary:hover { background: #48484a; }
  .btn--ghost:hover { background: #3a1a1a; border-color: #7a2020; }
  .dialog__icon-wrap { background: #3a1a1a; }
  dialog { background: var(--color-surface); }
}

/* ─── Forced colors ────────────────────────────────────────────── */
@media (forced-colors: active) {
  .btn { forced-color-adjust: none; border: 2px solid ButtonText; }
  dialog { border: 2px solid CanvasText; }
  .image-card { border: 1px solid CanvasText; }
}

/* ─── Narrow viewports / reflow ────────────────────────────────── */
@media (max-width: 480px) {
  .image-grid { grid-template-columns: 1fr; }
  .dialog__footer { flex-direction: column-reverse; }
  .dialog__footer .btn { width: 100%; justify-content: center; }
}
