const { chromium } = require('playwright');
const path = require('path');
const fs   = require('fs');

const AXE_PATH  = '/tmp/axe.min.js';
const HTML_FILE = path.resolve(__dirname, 'index.html');

(async () => {
  const browser = await chromium.launch();
  const context = await browser.newContext();
  const page    = await context.newPage();

  // Suppress console noise from the page
  page.on('console', () => {});
  page.on('pageerror', () => {});

  await page.goto('file://' + HTML_FILE, { waitUntil: 'networkidle' });
  await page.addScriptTag({ path: AXE_PATH });

  // ── State 1: dialog closed ──────────────────────────────────────────────
  const r1 = await page.evaluate(async () => await window.axe.run());

