  await page.click('.trigger');
  await page.waitForSelector('dialog[open]');
  const r2 = await page.evaluate(async () => await window.axe.run());

  await browser.close();

  // ── Merge & classify violations ─────────────────────────────────────────
  function classify(violations) {
    return {
      wcag: violations.filter(v => !v.tags.includes('best-practice')),
      bp:   violations.filter(v =>  v.tags.includes('best-practice')),
    };
  }

  const s1 = classify(r1.violations);
  const s2 = classify(r2.violations);

  function fmt(violations) {
    return violations.map(v => ({
      id:      v.id,
      impact:  v.impact,
      targets: v.nodes.map(n => n.target),
      desc:    v.description,
    }));
  }

  const report = {
