    dialog_open:   { wcag: fmt(s2.wcag), best_practice: fmt(s2.bp) },
  };

  fs.writeFileSync('/tmp/axe-report.json', JSON.stringify(report, null, 2));
  console.log(JSON.stringify(report, null, 2));

  const totalWcag = s1.wcag.length + s2.wcag.length;
  process.exit(totalWcag > 0 ? 1 : 0);
})();
