            </button>
          </div>
        </div>
      </article>
    </li>
  `.trim();
}

// ─── Dialog open / close ───────────────────────────────────────────────────

function openDialog(imageId) {
  const img = state.images.find((i) => i.id === imageId);
  if (!img) return;

  state.pendingDeleteId = imageId;

  // Populate dialog preview
  dialogImg.src = img.src;
  dialogImg.alt = img.alt;
  dialogName.textContent = `"${img.name}"`;

  dialog.showModal();

  // Move initial focus to the Cancel button (not the destructive action)
  dialog.querySelector("#btn-cancel").focus();
}

function closeDialog(confirmed) {
  dialog.close(confirmed ? "delete" : "cancel");
}

// ─── Dialog close handler ──────────────────────────────────────────────────

dialog.addEventListener("close", () => {
  if (dialog.returnValue === "delete" && state.pendingDeleteId) {
    const id = state.pendingDeleteId;
    const img = state.images.find((i) => i.id === id);
    const name = img ? img.name : "Image";

    state.images = state.images.filter((i) => i.id !== id);
