    const id = state.pendingDeleteId;
    const img = state.images.find((i) => i.id === id);
    const name = img ? img.name : "Image";

    state.images = state.images.filter((i) => i.id !== id);
    state.pendingDeleteId = null;
    renderGallery();
    announce(`"${name}" has been deleted from your library.`);
  } else {
    state.pendingDeleteId = null;
  }

  // Native <dialog> restores focus to the trigger automatically.
  // Nothing extra needed here unless the trigger was removed from the DOM
  // (which it is after deletion — so we fall back to focusing the gallery).
  if (dialog.returnValue === "delete") {
    const firstTrigger = gallery.querySelector(".trigger");
    if (firstTrigger) {
      firstTrigger.focus();
    } else {
      document.getElementById("main-heading").focus();
    }
  }
});

