document.getElementById("btn-cancel").addEventListener("click", () => closeDialog(false));
document.getElementById("btn-delete").addEventListener("click", () => closeDialog(true));

// Clicking the backdrop closes the dialog (cancel semantics for this non-destructive path)
dialog.addEventListener("click", (e) => {
  if (e.target === dialog) closeDialog(false);
});

